    if "debug" in raw:
        parsed["debug"] = bool(raw["debug"])

    if "page_size" in raw:
        page_size = int(raw["page_size"])
        if page_size < 1 or page_size > 100:
            raise ValueError("page_size must be between 1 and 100")
